def run(xs):
    acc = 0
    for i, x in enumerate(xs):
        branch = x % 3
        if branch == 0:
            acc = (acc * 7 + x) % 1000003
        elif branch == 1:
            shift = (i % 5) if x < 9950 else 0
            acc = (acc ^ (x << shift)) % 1000003
        else:
            acc = (acc + x * x) % 1000003
    return acc
